// Arma lo que lee Sofía en cada turno: la fecha, quién escribe, lo que ya se
// habló y lo nuevo. La memoria la pone el CRM: en cada mensaje manda el
// `historial` (lo anterior) y `mensajes` (lo que acaba de escribir el paciente;
// si mandó tres seguidos, llegan los tres juntos).
const b = $input.first().json.body || {};

const ahora = new Date().toLocaleString('es-MX', {
  timeZone: 'America/Cancun', weekday: 'long', day: 'numeric', month: 'long',
  year: 'numeric', hour: '2-digit', minute: '2-digit',
});
const c = b.contacto || {};
const quien = c.nombre
  ? `El paciente se llama ${c.nombre} (etapa: ${c.etapa || 'contacto'}).`
  : 'Todavía no sabes cómo se llama el paciente.';

const ROL = { paciente: 'Paciente', sofia: 'Sofía', operador: 'Equipo de la clínica' };
const antes = (b.historial || []).map((m) => `${ROL[m.rol] || m.rol}: ${m.texto}`).join('\n')
  || '(es el primer mensaje)';
const nuevo = (b.mensajes || [])
  .map((m) => m.texto || m.transcripcion || `[mandó un ${m.tipo} que no puedes ver]`)
  .join('\n');

return [{
  json: {
    prompt: `Hoy es ${ahora} (hora de Cancún). Canal: ${b.conversacion?.canal}. ${quien}\n\n`
      + `Conversación hasta ahora:\n${antes}\n\nMensajes nuevos del paciente:\n${nuevo}`,
  },
}];

// Si Sofía falla (OpenAI sin saldo, clave mala, una herramienta caída…), la
// conversación pasa a una persona en ese momento, con el mensaje de derivación del
// agente. Sin esto, n8n le contestaría al CRM un 200 vacío y el paciente esperaría
// 10 minutos.
const error = $input.first().json.error;
const crudo = typeof error === 'string' ? error : (error?.message || 'error desconocido');
// Algunos errores de n8n traen un enlace en HTML al final: se queda solo el texto.
const motivo = crudo.split('<')[0].replace(/\s+/g, ' ').trim() || 'error desconocido';
return [{ json: { acciones: { pasar_a_humano: `Sofía en n8n falló: ${motivo}`.slice(0, 200) } } }];

// Las fotos de cada tratamiento. Cambia las URL por las de tu clínica: públicas
// (https://), JPG o PNG, de hasta 5 MB. «Arma la respuesta» las adjunta.
const FOTOS = {
  blanqueamiento: {
    url: 'https://clinicasonrisaperfecta.site/media/fotos/blanqueamiento.jpg',
    pie: 'Blanqueamiento en Sonrisa Perfecta',
  },
  ortodoncia: {
    url: 'https://clinicasonrisaperfecta.site/media/fotos/ortodoncia.jpg',
    pie: 'Ortodoncia en Sonrisa Perfecta',
  },
  implantes: {
    url: 'https://clinicasonrisaperfecta.site/media/fotos/implantes.jpg',
    pie: 'Implantes en Sonrisa Perfecta',
  },
};

const pedido = String(query.tratamiento || '').normalize('NFD')
  .replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const foto = FOTOS[pedido];
if (!foto) {
  return `No tengo fotos de «${pedido}». Tengo de: ${Object.keys(FOTOS).join(', ')}.`;
}
return JSON.stringify({ listo: true, tratamiento: pedido, url: foto.url, pie: foto.pie,
  nota: 'La foto sale junto con tu respuesta. No pegues la dirección en el texto.' });

