// Traduce lo que hizo Sofía al formato del CRM:
//   respuesta → el texto para el paciente
//   archivos  → la foto, si usó «mandar_foto»
//   acciones.pasar_a_humano → el motivo, si usó «pasar_a_persona»
const r = $input.first().json;
const pasos = r.intermediateSteps || [];
const usadas = (nombre) => pasos.filter((p) => p.action?.tool === nombre);

// n8n envuelve lo que devuelve cada herramienta ([{"response": "…"}]): se desenvuelve.
function leer(obs) {
  let v = obs;
  for (let i = 0; i < 6; i++) {
    if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) { return null; } continue; }
    if (Array.isArray(v)) { v = v[0]; continue; }
    if (v && typeof v === 'object' && v.response !== undefined) { v = v.response; continue; }
    break;
  }
  return v && typeof v === 'object' && !Array.isArray(v) ? v : null;
}

const archivos = [];
for (const p of usadas('mandar_foto')) {
  const f = leer(p.observation);
  // Sin foto de eso, no se adjunta nada: Sofía ya se lo explicó al paciente.
  if (f?.listo) archivos.push({ tipo: 'imagen', url: f.url, pie: f.pie, nombre: `${f.tratamiento}.jpg` });
}

const salida = { respuesta: String(r.output || '').trim() };
if (archivos.length) salida.archivos = archivos.slice(0, 3);

const derivar = usadas('pasar_a_persona')[0];
if (derivar) {
  salida.acciones = { pasar_a_humano: String(derivar.action.toolInput?.motivo || 'Sofía pidió ayuda') };
}
return [{ json: salida }];
